        ["Andranik Sargsyan u. a. (MI-GAN, Picsart AI Research)"] = "Andranik Sargsyan et al. (MI-GAN, Picsart AI Research)",
        ["BILDER VERBESSERN"] = "ENHANCE IMAGES",
        ["Das Modell malt die markierten Stellen passend zur Umgebung neu. Rückgängig mit Strg+Z. Noch einmal „Entfernen“ (anderes Modell, Markierung ergänzt) rechnet wieder vom Bild davor."] = "The model repaints the marked areas to match their surroundings. Undo with Ctrl+Z. Clicking “Remove” again (other model, extended marking) starts again from the image before.",
        ["Den zuletzt gemalten Strich wieder wegnehmen."] = "Take back the last stroke.",
        ["Die Modelle laufen komplett auf deinem Rechner. Nach dem Herunterladen stehen sie in den Rubriken „KI“ und „Entfernen“ zur Auswahl."] = "The models run entirely on your computer. After downloading they can be chosen in the “AI” and “Remove” sections.",
        ["Entfernen · {0:0} %"] = "Remove · {0:0} %",
        ["Entfernen"] = "Remove",
        ["ENTFERNEN"] = "REMOVE",
        ["BEGRADIGEN"] = "STRAIGHTEN",
        ["Entfernen · Modell wird geladen …"] = "Remove · loading model …",
        ["Entfernen: Wasserzeichen, Schrift oder Störendes übermalen und von der KI füllen lassen"] = "Remove: paint over watermarks, text or distractions and let the AI fill them",
        ["Entfernt"] = "Removed",
        ["Entfernt nach {0:0.0} s — rückgängig mit Strg+Z. Anderes Modell oder Markierung ergänzt: noch einmal „Entfernen“ rechnet wieder vom Bild davor."] = "Removed after {0:0.0} s — undo with Ctrl+Z. Other model or extended marking: “Remove” again starts from the image before.",
        ["GESICHTER"] = "FACES",
        ["GESICHTSERKENNUNG"] = "FACE DETECTION",
        ["Größe des Pinsels auf dem Bildschirm. Zum genauen Malen mit Strg + Mausrad hineinzoomen — der Pinsel bleibt gleich groß."] = "Brush size on screen. Zoom in with Ctrl + mouse wheel to paint precisely — the brush keeps its size.",
        ["Hilfsmodelle für die Gesichtsmodelle: finden Gesichter und ihre Bereiche. Werden mit jedem Gesichtsmodell automatisch geladen."] = "Helper models for the face models: find faces and their regions. Downloaded automatically with every face model.",
        ["Kleine Stellen – schnell und klein"] = "Small areas – fast and small",
        ["LaMa (big-lama): malt markierte Stellen passend zur Umgebung neu, auch größere Flächen und Muster wie Mauern, Gras oder Himmel. Etwas langsamer."] = "LaMa (big-lama): repaints marked areas to match their surroundings, including larger areas and patterns such as walls, grass or sky. Somewhat slower.",
        ["LaMa (gründlich)"] = "LaMa (thorough)",
        ["Läuft lokal auf deinem Rechner. Nur bei eigenen Bildern oder mit Erlaubnis: Wasserzeichen aus fremden Bildern zu entfernen kann gegen das Urheberrecht verstoßen."] = "Runs locally on your computer. Only for your own images or with permission: removing watermarks from other people’s images may infringe copyright.",
        ["Letzter Strich"] = "Last stroke",
        ["MI-GAN: kleines, schnelles Modell zum Entfernen. Gut für kleine Stellen wie Schriftzüge oder Flecken; bei großen Flächen ist LaMa meist besser."] = "MI-GAN: small, fast removal model. Good for small areas such as lettering or spots; for large areas LaMa is usually better.",
        ["MI-GAN (schnell)"] = "MI-GAN (fast)",
        ["Mit gedrückter Maustaste über alles malen, was verschwinden soll – lieber etwas großzügiger als zu knapp. Mehrere Stellen auf einmal gehen."] = "Hold the mouse button and paint over everything that should disappear – rather a little generously than too tight. Several areas at once are fine.",
        ["Neue Markierung"] = "New marking",
        ["Pinsel"] = "Brush",
        ["Rauschen, JPEG-Artefakte, Unschärfe, Vergrößern – in der Rubrik „KI“."] = "Noise, JPEG artefacts, blur, upscaling – in the “AI” section.",
        ["Roman Suvorov u. a. (LaMa, Samsung AI Center), ONNX von Carve"] = "Roman Suvorov et al. (LaMa, Samsung AI Center), ONNX by Carve",
        ["Unscharfe oder beschädigte Gesichter wiederherstellen – in der Rubrik „KI“."] = "Restore blurry or damaged faces – in the “AI” section.",
        ["Wasserzeichen, Schrift oder Störendes übermalen und füllen lassen – in der Rubrik „Entfernen“."] = "Paint over watermarks, text or distractions and let them be filled – in the “Remove” section.",
        ["Fotografierte, gewölbte oder zerknitterte Blätter mit einem Klick gerade ziehen – Symbol „KI begradigen“ in der Vorschau."] = "Flatten photographed curved or crumpled pages with one click – “Straighten with AI” icon in the preview.",
        ["Wasserzeichen, Schrift, Personen – beste Füllung"] = "Watermarks, text, people – best fill",
        ["Wasserzeichen · Schrift · Störendes"] = "Watermarks · text · distractions",
        ["Wird entfernt …"] = "Removing …",
        ["Zum Entfernen wird ein Modell gebraucht (LaMa oder MI-GAN). Es läuft komplett auf deinem Rechner und wird einmalig heruntergeladen."] = "Removing needs a model (LaMa or MI-GAN). It runs entirely on your computer and is downloaded once.",
        ["Luminanz hellt nur Bereiche auf, die dunkler sind als dieser Wert – ein dunkler Baum wird als Ganzes heller, der helle Himmel daneben und zwischen den Ästen bleibt. Ganz rechts: keine Grenze. Wirkt nur beim Aufhellen."] = "Luminance only brightens areas darker than this value – a dark tree becomes lighter as a whole, while the bright sky next to it and between the branches stays. Far right: no limit. Only applies when brightening.",
        ["Zielwert"] = "Target",
        ["+{0:0} % · bis {1:0} % · Verlauf {2:0}"] = "+{0:0} % · up to {1:0} % · gradient {2:0}",
        ["Ab dieser Helligkeit passiert nichts mehr – z. B. rund um die Sonne und im hellen Himmel. Darunter wird es zum Dunklen hin immer mehr."] = "Above this brightness nothing happens any more – e.g. around the sun and in the bright sky. Below it, the effect grows towards the dark.",
        ["Auslaufen"] = "Fade out",
        ["LUMINANZMASKE"] = "LUMINOSITY MASK",
        ["1 Linie"] = "1 line",
        ["{0} Linien"] = "{0} lines",
        ["Alle Linien entfernen. Übernommen wird erst mit „Gerade ziehen“."] = "Remove all lines. Nothing is applied until “Straighten out”.",
        ["Gerade gezogen"] = "Straightened out",
        ["Gerade ziehen"] = "Straighten out",
        ["Gerade ziehen entfernt"] = "Straightening removed",
        ["Gewölbtes Blatt"] = "Curved page",
        ["Gewölbtes Blatt gerade ziehen: Punkte auf Linien setzen, die in Wirklichkeit gerade sind – Textzeilen, Blattkanten, Tabellenlinien, bei Büchern der Falz. Daraus wird das Blatt geglättet und das Seitenverhältnis berechnet; das ganze Bild bleibt. Beim Ziehen hilft eine Lupe."] = "Straighten out a curved page: set points on lines that are straight in reality – text lines, page edges, table lines, the fold of a book. The page is flattened from them and its aspect ratio calculated; the whole image stays. A magnifier helps while dragging.",
        ["Alle unberührten Vorschläge entfernen. Eigene und geänderte Linien bleiben."] = "Remove all untouched suggestions. Your own and changed lines stay.",
        ["Keine Linien gefunden – bitte von Hand setzen."] = "No lines found – please set them by hand.",
        ["Linien suchen fehlgeschlagen: {0}"] = "Finding lines failed: {0}",
        ["Vorschlagen"] = "Suggest",
        ["Linien werden gesucht …"] = "Finding lines …",
        ["Sucht Textzeilen, Blattkanten und den Falz und legt sie gestrichelt über das Bild. Eigene und geänderte Linien bleiben; was schon auf einer eigenen Linie liegt, wird nicht noch einmal vorgeschlagen."] = "Finds text lines, page edges and the fold and lays them dashed over the image. Your own and changed lines stay; whatever already lies on one of your lines is not suggested again.",
        ["Vorschläge weg"] = "Clear suggestions",
        ["Zeichnen"] = "Draw",
        ["Zeichnen: jeder Klick setzt einen Punkt, Enter oder Doppelklick beginnt die nächste Linie, Esc beendet das Zeichnen (auch mit N einschalten). Aus: Ziehen verschiebt das Bild, Ziehen an einem Punkt den Punkt."] = "Drawing: every click sets a point, Enter or double-click starts the next line, Esc ends drawing (N also switches it on). Off: dragging moves the image, dragging a point moves the point.",
        ["Ziehen verschiebt das Bild, Ziehen an einem Punkt den Punkt. Klick auf eine Linie: an ihr weiterzeichnen (am näheren Ende). „Zeichnen“: jeder Klick setzt einen Punkt, Enter oder Doppelklick beginnt die nächste Linie, Esc beendet das Zeichnen. Blau: waagerecht auf dem Blatt, orange: senkrecht, pink: Falz – Rechtsklick wechselt. Das × an einer Linie entfernt sie; gestrichelt = Vorschlag, eine Änderung macht ihn zur eigenen Linie. Verlassen über das Symbol oben."] = "Dragging moves the image, dragging a point moves the point. A click on a line: keep drawing on it (at its nearer end). “Draw”: every click sets a point, Enter or double-click starts the next line, Esc ends drawing. Blue: horizontal on the page, orange: vertical, pink: fold – right-click switches. The × at a line removes it; dashed = suggestion, any change makes it your own line. Leave via the icon at the top.",
        ["Vorgeschlagen: {0} Textzeilen, {1} Blattkanten, {2} gezeichnete Linien, {3} Flächenkanten, {4} Textränder, {5} Falz – Klick auf eine Linie zeichnet an ihr weiter, das × entfernt sie."] = "Suggested: {0} text lines, {1} page edges, {2} drawn lines, {3} box edges, {4} text margins, {5} fold – a click on a line keeps drawing on it, the × removes it.",
        ["KI begradigen: ein Klick, keine Linien – das Modell SyntheticDoc zieht das fotografierte Blatt gerade. Gut bei zerknitterten Blättern, Bons in der Hand und Büchern; bei glatten Arbeitsblättern ist „Gewölbtes Blatt“ mit Linien genauer. Ein zweiter Klick nimmt die Begradigung wieder heraus. Rechtsklick: Schatten entfernen ein oder aus. Braucht das Modell SyntheticDoc (Tab KI)."] = "Straighten with AI: one click, no lines – the SyntheticDoc model flattens the photographed page. Good for crumpled sheets, receipts held in the hand and books; for flat worksheets “Curved page” with lines is more precise. A second click removes it again. Right-click: remove shadows on or off. Needs the SyntheticDoc model (AI tab).",
        ["KI-Begradigung entfernt"] = "AI straightening removed",
        ["Das Modell „{0}“ fehlt – im Tab KI herunterladen."] = "The model “{0}” is missing – download it in the AI tab.",
        ["KI-Modell wird vorbereitet …"] = "Preparing the AI model …",
        ["KI begradigt …"] = "AI straightening …",
        ["KI begradigt"] = "AI straightened",
        ["Schatten entfernen"] = "Remove shadows",
        ["Schatten entfernt"] = "Shadows removed",
        ["Schatten wieder drin"] = "Shadows restored",
        ["KI begradigen fehlgeschlagen: {0}"] = "AI straightening failed: {0}",
        ["KI (SyntheticDoc)"] = "AI (SyntheticDoc)",
        ["SyntheticDoc"] = "SyntheticDoc",
        ["Gewölbtes Blatt mit KI begradigen – Bons, Bücher, zerknitterte Blätter"] = "Straighten a curved page with AI – receipts, books, crumpled sheets",
        ["SyntheticDoc: begradigt ein fotografiertes Blatt mit einem Klick, ohne Linien. Stark bei Knittern, Bons in der Hand und Büchern; bei glatten Arbeitsblättern ist „Gewölbtes Blatt“ mit Linien genauer. Wird beim ersten Gebrauch für die App umgewandelt."] = "SyntheticDoc: flattens a photographed page with one click, no lines. Strong on crumples, receipts held in the hand and books; for flat worksheets “Curved page” with lines is more precise. Converted for the app on first use.",
        ["Daniel Woortmann, Tanguy Magne, Olga Sorkine-Hornung (SyntheticDoc, ECCV 2026, ETH Zürich)"] = "Daniel Woortmann, Tanguy Magne, Olga Sorkine-Hornung (SyntheticDoc, ECCV 2026, ETH Zurich)",
        ["1 Vorschlag passte nicht zu den übrigen und wurde weggelassen."] = "1 suggestion did not fit the others and was left out.",
        ["1 Vorschlag lag auf einer eigenen Linie und wurde weggelassen."] = "1 suggestion lay on one of your lines and was left out.",
        ["{0} Vorschläge passten nicht zu den übrigen und wurden weggelassen."] = "{0} suggestions did not fit the others and were left out.",
        ["{0} Vorschläge lagen auf eigenen Linien und wurden weggelassen."] = "{0} suggestions lay on your lines and were left out.",
        ["Linien werden geprüft …"] = "Checking lines …",
        ["Mit diesen Linien lässt sich nichts gerade ziehen."] = "Nothing can be straightened out with these lines.",
        ["Linien vorschlagen lassen oder Punkte auf eine Linie setzen, die eigentlich gerade ist."] = "Have lines suggested or set points on a line that is actually straight.",
        ["Seite 1 : {0:0.00}"] = "Page 1 : {0:0.00}",
        ["Seite 1 : {0:0.00} (DIN)"] = "Page 1 : {0:0.00} (ISO)",
        ["Zieht das Blatt gerade und schneidet auf das größte volle Rechteck zu – ein Schritt, Strg+Z macht ihn rückgängig. Auch mit Enter (ohne aktive Linie)."] = "Straightens out the page and crops to the largest full rectangle – one step, Ctrl+Z undoes it. Also with Enter (without an active line).",
        ["keine Linien"] = "no lines",
        ["nur die Linien gerade gezogen – für das ganze Blatt mehr Linien setzen"] = "only the lines straightened – set more lines for the whole page",
        ["KÖRNUNG"] = "GRAIN",
        ["Rauheit"] = "Roughness",
        ["Härte"] = "Hardness",
        ["Weich: Körner als sanfte Tupfen. Mehr: scharf begrenzte Körner mit steilen Rändern – das Bild wirkt körniger, bei gleicher Stärke und Größe."] = "Soft: grains as gentle dabs. More: sharply bounded grains with steep edges – the image looks grainier at the same strength and size.",
        ["Farbanteil"] = "Colour share",
        ["gleichmäßig"] = "even",
        ["Aus dem Foto ermitteln"] = "Measure from the photo",
        ["Wie viel Korn über das fertige Bild kommt – wie bei Film in den Mitteltönen am meisten, in Schwarz und Weiß fast nichts. Kommt immer zuletzt, nach Schärfen und KI."] = "How much grain is laid over the finished image – like film, most in the mid-tones, almost none in black and white. Always applied last, after sharpening and AI.",
        ["Von 0,1 px (feiner als ein Pixel: ohne grobe Häufungen) über 0,25 px (Pixel für Pixel) bis grob. Gilt für die Ausgabegröße – beim Verkleinern sieht das Korn gleich aus."] = "From 0.1 px (finer than a pixel: without coarse clusters) through 0.25 px (pixel by pixel) to coarse. Refers to the output size – the grain looks the same when downsizing.",
        ["Gleichmäßig wie ein Sensor oder klumpig wie Film: mischt gröberes Korn dazu und lässt die Stärke großflächig schwanken."] = "Even like a sensor or clumpy like film: mixes in coarser grain and lets the strength vary over larger areas.",
        ["Aus: reines Helligkeitskorn wie bei Schwarzweißfilm. Mehr: zusätzlich bunte Körnchen, jeder Farbkanal für sich."] = "Off: pure luminance grain like black-and-white film. More: additional coloured specks, each colour channel on its own.",
        ["Misst das Korn des Fotos (vor KI und Entrauschen) und stellt Stärke, Korngröße und Farbanteil so ein, dass es wieder so aussieht – sinnvoll nach „Rauschen“ oder KI. Danach lässt sich alles nachbessern; Rückgängig mit Strg+Z."] = "Measures the grain of the photo (before AI and noise reduction) and sets strength, grain size and colour share so it looks like that again – useful after “Noise” or AI. Everything can be fine-tuned afterwards; undo with Ctrl+Z.",
        ["Korn wird gemessen …"] = "Measuring grain …",
        ["Im Foto ist kein Korn messbar – es ist schon ganz glatt."] = "No grain can be measured in the photo – it is already completely smooth.",
        ["Korn aus dem Foto übernommen – Regler lassen sich nachbessern."] = "Grain taken from the photo – the sliders can be fine-tuned.",
        ["Korn messen fehlgeschlagen: {0}"] = "Measuring grain failed: {0}",
        ["Luminanzmaske"] = "Luminosity mask",
        ["Maske zeigen"] = "Show mask",
        ["Verlauf"] = "Gradient",
        ["Weich: auch Felder und Himmel bekommen etwas mit. Steil: nur das wirklich Dunkle (wie Darks II, III in Referenzwerkzeug)."] = "Soft: fields and sky get some too. Steep: only the really dark (like Darks II, III in Referenzwerkzeug).",
        ["Wie viel heller das Dunkelste wird. Mitteltöne bekommen anteilig weniger, helle Bereiche nichts – die Maske folgt jedem Zweig, ohne Hof."] = "How much brighter the darkest parts become. Mid-tones get proportionally less, bright areas nothing – the mask follows every twig, without a halo.",
        ["Zeigt die Maske als Graustufen: weiß bekommt die volle Stärke, schwarz nichts. Nur zum Einstellen – der Export bleibt das Bild."] = "Shows the mask in greyscale: white gets the full strength, black nothing. Only for adjusting – the export stays the image.",
        ["steil"] = "steep",
        ["weich"] = "soft",
        ["Gesamt"] = "Overall",
        ["Luminanz für das ganze Bild, ohne Bereiche und Masken: macht alles im selben Verhältnis heller oder dunkler, Weiß läuft weich aus. Wirkt nach der Luminanz darunter – erst die Bereiche angleichen, dann das Ganze heller machen."] = "Luminance for the whole image, without areas or masks: makes everything lighter or darker in the same proportion, white rolls off softly. Applies after the luminance below – first even out the areas, then brighten the whole.",
        ["Hellt dunkle Bereiche nur bis zu dieser Helligkeit auf: ein dunkler Baum bekommt viel, eine Wiese im Mittelton kaum etwas – so strahlt nichts über. Luminanz bestimmt, wie stark höchstens. Ganz links: aus, alles wird im selben Verhältnis heller. Wirkt nur beim Aufhellen."] = "Brightens dark areas only up to this level: a dark tree gets a lot, a mid-tone meadow hardly anything – so nothing gets blown out. Luminance sets the maximum. Far left: off, everything gets brighter in the same proportion. Only applies when brightening.",
        ["Wie „Gleiche Farbe“ in Referenzwerkzeug CS5: rechnet die Helligkeit hoch statt sie nur anzuheben — das Bild wird leuchtender, die Kontraste bleiben. Weiß läuft weich aus, nichts frisst aus. Über 200 % (bis 300 %) vor allem zusammen mit dem Zielwert: dann erreichen auch tiefe Schatten das Ziel, Mitteltöne bleiben ruhig."] = "Like “Match Color” in Referenzwerkzeug CS5: scales the brightness up instead of just lifting it — the image becomes more luminous and the contrasts stay. White rolls off softly, nothing blows out. Above 200 % (up to 300 %) mainly together with the target value: then even deep shadows reach the target while mid-tones stay calm.",
        ["Ausgleichen"] = "Neutralise",
        ["Entfernt einen Farbstich (z. B. gelbes Kunstlicht, blauer Schatten): Graues und Weißes wird wieder neutral. Der Regler bestimmt, wie viel davon. Kräftige Farben zählen bei der Erkennung nicht mit."] = "Removes a colour cast (e.g. yellow artificial light, blue shade): greys and whites become neutral again. The slider sets how much. Strong colours are not counted when detecting the cast.",
        ["Links kühler (bläulich), rechts wärmer (gelblich), Mitte neutral — z. B. wenn Ausgleichen ein Kunstlicht-Foto zu kühl gemacht hat."] = "Left cooler (bluish), right warmer (yellowish), centre neutral — e.g. when neutralising made an artificial-light photo too cool.",
        ["Zurücksetzen"] = "Reset",
        ["Alle Regler dieser Kachel auf 0, Färben aus. Rückgängig mit Strg+Z."] = "All sliders in this section to 0, tint off. Undo with Ctrl+Z.",

        // ------------------------------------------------------------ Ausgabe
        ["METADATEN & FARBE"] = "METADATA & COLOUR",
        ["EXIF/IPTC/XMP: Kamera, Datum, Ort, Copyright. „Nur GPS entfernen“ löscht die Ortsangaben — sinnvoll vor dem Teilen im Netz."] = "EXIF/IPTC/XMP: camera, date, location, copyright. “Remove GPS only” deletes the location — sensible before sharing online.",
        ["Alles behalten"] = "Keep everything",
        ["Nur GPS entfernen"] = "Remove GPS only",
        ["Alles entfernen"] = "Remove everything",
        ["ICC-Profil"] = "ICC profile",
        ["Profil behalten: Farbraum wie im Original (z. B. Adobe RGB für den Druck). Nach sRGB: überall richtige Farben — Standard fürs Web. Profil verwerfen: sRGB ohne eingebettetes Profil, etwas kleinere Datei."] = "Keep profile: colour space as in the original (e.g. Adobe RGB for print). To sRGB: correct colours everywhere — the standard for the web. Discard profile: sRGB without an embedded profile, slightly smaller file.",
        ["Profil behalten"] = "Keep profile",
        ["Nach sRGB wandeln"] = "Convert to sRGB",
        ["Profil verwerfen"] = "Discard profile",
        ["AUSGABE"] = "OUTPUT",
        ["Dateiname"] = "File name",
        ["Platzhalter: {name} Dateiname ohne Endung · {breite} {höhe} Pixelmaße · {n} laufende Nummer · {datum} heutiges Datum. Die Endung kommt automatisch dazu."] = "Placeholders: {name} file name without extension · {breite} {höhe} width and height in pixels · {n} running number · {datum} today's date. The extension is added automatically.",

