        // KI-Modelle (Einstellungen)
        ["KI-Modelle"] = "AI models",
        ["Ordner:"] = "Folder:",
        ["Modelle lassen sich auch von Hand hineinlegen (je Modell ein Unterordner) — die App erkennt sie automatisch."] = "Models can also be placed there by hand (one subfolder per model) — the app detects them automatically.",
        ["Herunterladen"] = "Download",
        ["Löschen"] = "Delete",
        ["Modell von der Festplatte entfernen. Es lässt sich jederzeit neu laden."] = "Remove the model from the disk. It can be downloaded again at any time.",
        ["{0}  ·  Lizenz {1}"] = "{0}  ·  License {1}",
        ["(nur nicht-kommerziell)"] = "(non-commercial only)",
        ["wird geladen …"] = "downloading …",
        ["✓ vorhanden"] = "✓ installed",
        ["nicht geladen"] = "not downloaded",
        ["Download fehlgeschlagen: {0}"] = "Download failed: {0}",
        ["Gerade läuft eine KI-Berechnung — danach löschen."] = "An AI calculation is running — delete afterwards.",
        ["Löschen fehlgeschlagen: {0}"] = "Delete failed: {0}",
        ["Die heruntergeladene Datei ist beschädigt oder wurde verändert (Prüfsumme stimmt nicht)."] = "The downloaded file is damaged or has been modified (checksum does not match).",
        ["Allround (klein)"] = "All-round (small)",
        ["Rauschen, JPEG-Artefakte, leichte Unschärfe"] = "Noise, JPEG artefacts, slight blur",
        ["Real-ESRGAN „general x4v3“: kleines, schnelles Modell für Fotos aus Handy und Netz. Entfernt Rauschen und Kompressionsblöcke und macht Kanten klarer. Kann vergrößern (bis 4×)."] = "Real-ESRGAN “general x4v3”: small, fast model for photos from phones and the web. Removes noise and compression blocks and makes edges clearer. Can upscale (up to 4×).",
        ["Xintao Wang (Real-ESRGAN), ONNX von Qualcomm AI Hub"] = "Xintao Wang (Real-ESRGAN), ONNX by Qualcomm AI Hub",
        ["Gesichtserkennung"] = "Face detection",
        ["Findet Gesichter für die Gesichtsmodelle"] = "Finds faces for the face models",
        ["YuNet (OpenCV): sehr kleines Modell, das Gesichter und Augen, Nase, Mund findet. Wird mit jedem Gesichtsmodell automatisch geladen."] = "YuNet (OpenCV): very small model that finds faces and eyes, nose, mouth. Downloaded automatically with every face model.",
        ["Shiqi Yu u. a. (OpenCV Zoo), ONNX von FaceFusion"] = "Shiqi Yu et al. (OpenCV Zoo), ONNX by FaceFusion",
        ["Gesichter – GFPGAN 1.4"] = "Faces – GFPGAN 1.4",
        ["Augen, Mund, Haut bei unscharfen Gesichtern"] = "Eyes, mouth, skin in blurry faces",
        ["GFPGAN 1.4: stellt unscharfe oder kleine Gesichter natürlich wieder her. Nur die Gesichter werden verändert, der Rest des Bildes bleibt, wie er ist."] = "GFPGAN 1.4: restores blurry or small faces naturally. Only the faces are changed, the rest of the image stays as it is.",
        ["TencentARC (GFPGAN), ONNX von FaceFusion"] = "TencentARC (GFPGAN), ONNX by FaceFusion",
        ["Gesichter – GFPGAN 1.3"] = "Faces – GFPGAN 1.3",
        ["Natürlicher, etwas weicher als 1.4"] = "More natural, a little softer than 1.4",
        ["GFPGAN 1.3: ältere Fassung von GFPGAN, laut den Entwicklern natürlicher und mit weniger künstlichen Details als 1.4. Nur die Gesichter werden verändert, der Rest des Bildes bleibt, wie er ist."] = "GFPGAN 1.3: older version of GFPGAN, according to its developers more natural and with fewer artificial details than 1.4. Only the faces are changed, the rest of the image stays as it is.",
        ["Gesichter – RestoreFormer++"] = "Faces – RestoreFormer++",
        ["Echte, unscharfe Fotos, hält die Person gut"] = "Real blurry photos, keeps the person recognisable",
        ["RestoreFormer++: neueres Modell für echte, unscharfe oder verrauschte Fotos. Bleibt meist nah an der Person und erfindet weniger Details. Nur die Gesichter werden verändert."] = "RestoreFormer++: newer model for real blurry or noisy photos. Usually stays close to the person and invents fewer details. Only the faces are changed.",
        ["Gesichter – CodeFormer"] = "Faces – CodeFormer",
        ["Stark beschädigte Gesichter, alte Fotos"] = "Badly damaged faces, old photos",
        ["CodeFormer: kommt auch mit sehr schlechten Gesichtern zurecht (alte Fotos, starke Kompression). Nur die Gesichter werden verändert. Lizenz erlaubt nur nicht-kommerzielle Nutzung."] = "CodeFormer: copes even with very poor faces (old photos, heavy compression). Only the faces are changed. The license allows non-commercial use only.",
        ["Shangchen Zhou (CodeFormer), ONNX von FaceFusion"] = "Shangchen Zhou (CodeFormer), ONNX by FaceFusion",
        ["Zhouxia Wang u. a. (RestoreFormer++), ONNX von FaceFusion"] = "Zhouxia Wang et al. (RestoreFormer++), ONNX by FaceFusion",

        // ------------------------------------------------------------ Einstellungen, Sprache
        ["Einstellungen"] = "Settings",
        ["Schließen"] = "Close",
        ["Laufende Downloads gehen im Hintergrund weiter."] = "Running downloads continue in the background.",
        ["Sprache"] = "Language",
        ["Weitere Sprachen: eine JSON-Datei in den Ordner „languages“ neben dem Programm legen. Die Vorlage enthält alle Texte mit englischer Übersetzung zum Übersetzen."] = "More languages: put a JSON file into the “languages” folder next to the program. The template contains every text with its English translation to translate from.",
        ["Vorlage erstellen"] = "Create template",
        ["Schreibt _vorlage.json in den Ordner languages. Kopieren, umbenennen (z. B. fr.json), Code, Name, Flagge und Texte übersetzen."] = "Writes _vorlage.json into the languages folder. Copy it, rename it (e.g. fr.json), then fill in code, name, flag and translate the texts.",
        ["Nicht geladene Sprachdateien:"] = "Language files not loaded:",
        ["Kein Dateimanager gefunden. Ordner: {0}"] = "No file manager found. Folder: {0}",
        ["Vorlage gespeichert: {0}"] = "Template saved: {0}",
        ["Vorlage ließ sich nicht speichern: {0}"] = "Could not save the template: {0}",
        ["Kein Schreibrecht im Ordner {0}"] = "No write permission in the folder {0}",
        ["{0}: Deutsch ist eingebaut und lässt sich nicht ersetzen."] = "{0}: German is built in and cannot be replaced.",
        ["kein JSON-Objekt"] = "not a JSON object",

        // Frei drehen
        ["Frei drehen: mit dem Regler unten um einen beliebigen Winkel drehen, z. B. den Horizont gerade richten. Der Rahmen zeigt, was übrig bleibt – er passt sich beim Drehen an und lässt sich danach verschieben und verkleinern. „Drehen und zuschneiden“ übernimmt, Esc verwirft."] =
            "Rotate freely: turn the image by any angle with the slider below, e.g. to straighten the horizon. The frame shows what remains – it follows the angle and can then be moved and made smaller. “Rotate and crop” applies, Esc discards.",
        ["Drehen"] = "Rotate",
        ["Drehwinkel in Grad, positiv im Uhrzeigersinn. Pfeiltasten: 0,1°, Bild auf/ab: 1°."] = "Rotation angle in degrees, positive is clockwise. Arrow keys: 0.1°, Page up/down: 1°.",
        ["Drehung verwerfen (Esc)"] = "Discard rotation (Esc)",
        ["Drehen und zuschneiden"] = "Rotate and crop",
        ["Dreht das Bild und schneidet es auf den Rahmen zu – ein Schritt, Strg+Z macht ihn rückgängig. Auch mit Enter oder Doppelklick in den Rahmen."] =
            "Rotates the image and crops it to the frame – one step, Ctrl+Z undoes it. Also with Enter or a double-click inside the frame.",
        ["Gedreht"] = "Rotated",
        ["Gerade gerichtet"] = "Levelled",
        ["gespiegelt"] = "flipped",
        ["{0} × {1} px · runde Ecken"] = "{0} × {1} px · rounded corners",

        // Entzerren
        ["Entzerren: die vier Ecken des Rahmens auf die Ecken von etwas legen, das in Wirklichkeit rechteckig ist – Blatt, Bild an der Wand, Fenster, Hausfront. Daraus wird ein gerades Rechteck, genau der Inhalt des Rahmens. Beim Ziehen hilft eine Lupe; Pfeiltasten verschieben die zuletzt gezogene Ecke um 1 px (Umschalt: 10 px)."] =
            "Straighten perspective: put the four corners of the frame on the corners of something that is really rectangular – a sheet, a picture on the wall, a window, a facade. It becomes a straight rectangle, exactly the content of the frame. A magnifier helps while dragging; arrow keys move the last dragged corner by 1 px (Shift: 10 px).",
        ["Entzerren"] = "Straighten",
        ["Die Ecken überkreuzen sich – bitte so legen, dass ein Viereck entsteht."] = "The corners cross – please place them so that they form a quadrilateral.",
        ["Ergebnis: {0} × {1} px"] = "Result: {0} × {1} px",
        ["Entzerren und zuschneiden"] = "Straighten and crop",
        ["Macht aus dem Rahmen ein gerades Rechteck – ein Schritt, Strg+Z macht ihn rückgängig. Auch mit Enter oder Doppelklick in den Rahmen; Esc bricht ab."] =
            "Turns the frame into a straight rectangle – one step, Ctrl+Z undoes it. Also with Enter or a double-click inside the frame; Esc cancels.",
        ["Entzerrt"] = "Straightened",

        // Standardformate
        ["Standardformat wählen (A4, A5, Fotoabzüge …): Das Bild wird in Millimetern darauf gebracht – Hoch- oder Querformat wie das Bild, bei geschlossener Kette ganz hinein mit gleichem Seitenverhältnis. Die DPI bleibt (für den Druck 300 einstellen); bei „Nur Metadaten ändern“ ändert sich statt der Pixel die DPI."] =
            "Choose a standard format (A4, A5, photo prints …): the image is brought to it in millimetres – portrait or landscape like the image, with the chain closed fully inside with the same aspect ratio. The DPI stays (set 300 for printing); with “Only change metadata” the DPI changes instead of the pixels.",
